    summary: "现存最大的掠食性鲨鱼之一，背灰腹白、体形流线，嗅觉与电感受器极为灵敏，是海洋食物链的顶端捕食者。",
    description: "大白鲨体呈粗壮的纺锤形，吻部圆锥状，口内排列着数排三角形锯齿状牙齿，边缘锋利如刀。背部呈灰褐色或铅灰色，腹部雪白，背腹之间界线分明，这种反荫蔽配色使猎物难以发现它的接近。成鱼体长一般 4–5 m，体重 700–1000 kg，最大记录个体体长超过 6 m、体重约 2 t，是现存体型最大的掠食性鱼类之一。它的嗅觉极其灵敏，还能感知猎物肌肉收缩产生的微弱电场。\n\n大白鲨广泛分布于全球温带和亚热带海域，常在南非、澳大利亚南部、美国加州和地中海等海豹、海狮聚集的岛屿附近活动。它是少数能局部提高体温的鲨鱼，肌肉温度可比周围海水高 5–10 ℃，因而能在较冷的水中保持敏捷。它主要捕食海豹、海狮、鱼类和其他鲨鱼，常从下方突袭猎物；繁殖为卵胎生，妊娠期约一年，每胎 2–10 尾。由于鱼翅贸易、误捕和栖息地退化，全球种群持续下降，IUCN 将其评为易危，中国于 2021 年将其列为国家二级保护动物。",
