    description: "眼斑双锯鱼体呈椭圆形、侧扁，通体鲜橙色，体侧有 3 条镶黑边的白色竖带，背鳍、臀鳍和尾鳍的边缘也镶着黑色。成鱼体长一般 6–8 cm，最大约 11 cm，雌鱼比雄鱼略大。它的皮肤能分泌一层特殊黏液，这层黏液可以抑制海葵刺细胞的发射，使它能在海葵触手之间自由穿行，并把海葵当作睡觉和躲避天敌的庇护所。\n\n眼斑双锯鱼生活在印度洋至西太平洋的热带珊瑚礁，水深多在 1–15 m，以浮游甲壳类、藻类和海葵吃剩的残渣为食。每个海葵群里通常有一尾体型最大的雌鱼、一尾繁殖雄鱼和若干未成熟个体；它是雄性先熟的雌雄同体鱼类，若雌鱼死亡，最大的雄鱼会在数周内转变为雌鱼。繁殖时雌鱼在岩石表面产卵 100–1000 枚，雄鱼负责扇水护卵约 6–8 天。它也是水族贸易中交易量很大的观赏鱼，目前野外种群尚属稳定，IUCN 将其评为无危。",
