    description: "神仙鱼体侧扁呈菱形，背鳍和臀鳍高耸如燕翼，腹鳍延长成丝状，尾鳍浅叉；野生型体色银灰，体侧分布数条黑色竖带，眼睛上还有一道黑纹。经过长期人工选育，如今已有纯白、黑纱、大理石、金头等大量变异品系，体长可达 15 cm，连鳍高度可超过 25 cm。\n\n神仙鱼原产于南美洲亚马孙河、奥里诺科河及圭亚那的河流，喜欢水流缓慢、水草茂密、有沉木遮阴的水域，适宜水温 24–28 ℃、弱酸性软水。它是杂食性鱼类，以水生昆虫、甲壳类、小鱼和植物碎屑为食，性情相对温和，但繁殖期有较强的领域性。繁殖时雌鱼把卵产在叶片或石块上，每窝 200–400 枚，亲鱼会共同扇水护卵并带领幼鱼觅食，护幼行为在观赏鱼中十分典型。神仙鱼在中国主要作为人工养殖的观赏鱼，尚未被列入国家重点保护野生动物名录，也没有IUCN 的正式评估。",
