    description: "金鱼是野生鲫鱼的驯化变种，体形、体色和鳍形的变异极大：草种体形接近鲫鱼，文种体短而圆、尾鳍分叉，蛋种无背鳍、体呈卵形，龙种眼球外凸，水泡眼的眼睛下方还长着充满液体的液泡。体色有红、橙、白、黑、紫和花斑等，成鱼体长一般 10–20 cm，大型品种可超过 30 cm。\n\n中国自晋代就有红色鲫鱼的记载，唐代开始在放生池中人工饲养，宋代出现家养金鱼，明代培育出双尾、龙睛等品种，此后陆续传入日本、欧洲和美洲。金鱼是杂食性鱼类，以浮游动物、藻类、水生昆虫和人工饵料为食；繁殖期多在春季和秋季，雌鱼把卵产在水草上，每尾可产数千至数万粒，亲鱼不护卵。如今金鱼已在全球广泛饲养，野生化种群也见于多地池塘，作为人工培育品种，它没有IUCN 的评估，中国也未将其列入国家重点保护野生动物名录。",
