    description: "大西洋鲑体呈纺锤形，背部蓝灰或银蓝色，腹部银白，体侧散布黑色小点；繁殖期的雄鱼下颌延长成钩状，体侧出现红褐色斑纹，这被称为婚姻色。成鱼体长一般 60–90 cm，体重 3–9 kg，最大的个体可超过 1.3 m、体重 20 kg 以上。\n\n大西洋鲑是典型的溯河洄游鱼类：它们在淡水河流上游的砂砾河床中产卵，幼鱼在淡水中生活 1–3 年，变态为降海型后进入北大西洋，在格陵兰周边海域育肥 1–4 年，成熟后凭嗅觉记忆返回出生的河流，逆流而上回到产卵地。它肉食性，幼鱼吃水生昆虫，成鱼在海中捕食小鱼、虾和乌贼；秋季在河床挖坑产卵，产卵后多数亲鱼力竭而死，少数能再次回到海中。大西洋鲑原产北大西洋两岸，如今在挪威、智利等国被大规模养殖，是全球最重要的养殖鲑鱼。全球评估中 IUCN 将其评为无危，中国没有自然分布，也未将其列入国家重点保护野生动物名录。",
