    description: "达氏鲟体呈长纺锤形，吻部较中华鲟短而钝，口位于吻的腹面、呈横裂状，没有真正的牙齿。体表裸露无鳞，背部和体侧排列着五道骨板，背鳍位置靠后，尾鳍为歪形尾。成鱼体长一般 1–1.5 m，体重 10–30 kg，最大记录体长约 2 m、体重 50 kg 以上。体色灰褐，腹部黄白色，幼鱼体色较浅。\n\n达氏鲟是淡水定居性鱼类，与需要江海洄游的中华鲟不同，它终生生活在长江上游干流及支流的深水江段，主食底栖小鱼、虾蟹、水生昆虫和软体动物。它性成熟较早，雄性约 4–6 龄、雌性约 6–8 龄，繁殖期在春季，产卵场位于长江上游江段。由于葛洲坝、三峡等工程阻隔洄游通道，加上航运、采砂、污染和过度捕捞，达氏鲟野生种群在 20 世纪后期急剧萎缩，2022 年IUCN 将其评定为野外灭绝。中国将其列为国家一级保护动物，目前主要依靠人工繁殖和增殖放流维持种群，科研人员也在尝试重建自然繁殖群体。",
