    description: "哲罗鲑体呈长梭形，吻部尖，口大，口内和舌上都长着尖锐的牙齿。体色背部灰褐或褐绿色，体侧银红，繁殖期体侧和腹部会泛起鲜艳的红褐色，因此当地人称它“大红鱼”。体表鳞片细小，侧线明显。成鱼体长一般 70–120 cm，体重 5–20 kg，最大记录体长可超过 1.5 m、体重可达 50 kg 以上。\n\n哲罗鲑分布于欧亚大陆北部的寒冷河流和湖泊，包括俄罗斯西伯利亚、蒙古、中国东北的黑龙江流域和新疆的额尔齐斯河水系，喜欢水温低、溶氧高、水流湍急的溪流和深潭。它是肉食性鱼类，捕食鱼类、蛙类、水鸟和小型哺乳动物，是溪流生态系统中的顶级掠食者。繁殖期在秋季，亲鱼上溯到支流的砾石河床产卵，雌鱼可产数千至数万粒卵，产卵后多数亲鱼仍能存活并再次繁殖。由于过度捕捞、水坝建设和栖息地退化，哲罗鲑种群数量下降，IUCN 将其评为易危，中国将其列为国家二级保护动物。",
