    summary: "在江河孵化、游向大海育肥、成熟后逆流返回出生地繁殖的鲑鱼，产卵后多数亲鱼耗尽体力而死，是中国东北著名的洄游鱼类。",
    description: "大马哈鱼体呈长纺锤形，背部蓝绿或暗褐色，体侧银白，腹部白色；与很多鲑鱼不同，它的体侧没有明显的黑色斑点，繁殖期会出现暗红色的横斑。生殖期雄鱼下颌延长成钩状，背鳍变高，体色变深。成鱼体长一般 60–80 cm，体重 3–6 kg，最大记录超过 1 m、体重 15 kg 以上。\n\n大马哈鱼是典型的溯河洄游鱼类，分布于北太平洋两岸，从日本、俄罗斯远东、中国东北到北美西岸。幼鱼在淡水河流中孵化，顺流入海，在鄂霍次克海和白令海等海域育肥 2–4 年，成熟后凭嗅觉返回出生的河流，逆流上溯数百至上千千米，途中几乎不进食，靠消耗体内的脂肪和肌肉提供能量。繁殖期在秋季，雌鱼在砾石河床上挖坑产卵，雄鱼守护卵床，产卵后亲鱼大多力竭而死。中国黑龙江、乌苏里江和图们江流域是其洄游河流的南缘，历史上资源丰富，20 世纪后期因水坝、河道破坏和过度捕捞明显减少，如今建有繁育放流站。目前其全球评估为无危，中国未将其列入国家重点保护野生动物名录。",
    habitat: "北太平洋的寒温带海域育肥，秋季溯河到砾石河床的淡水河流产卵",
