    description: "红腹锯鲑脂鲤体呈卵圆形、侧扁而厚实，头大吻短，下颌突出，上下颌各有一排三角形的尖牙，咬合力量很强。腹部呈橙色至鲜红色，背部灰绿或黑灰色，体侧散布着细小的银白色斑点，鳍的颜色较深。成鱼体长一般 20–30 cm，最大约 40 cm。\n\n它分布于南美洲的亚马孙河、奥里诺科河和巴拉那河等水系，生活在缓流、浑浊的河流、湖泊和泛滥林水域中。红腹锯鲑脂鲤是肉食性鱼类，捕食鱼类、甲壳类、昆虫和水生无脊椎动物，也吃腐肉，常结成群体活动，遇到受伤的猎物时会群起而攻。繁殖期雌鱼在水草根系或沙床上产卵，雄鱼负责护卵。影视作品常把这种鱼描绘成凶残的“食人鱼”，实际上它主动攻击人的情况很少，多发生在食物匮乏或受到刺激时。它作为观赏鱼被引入多个国家，逃逸后在部分热带水域形成野外种群。目前它没有IUCN 的正式评估，中国也未将其列入国家重点保护野生动物名录。",
