    summary: "体侧带蓝色纵纹的小型鲤科鱼，因胚胎透明、繁殖快，成为生命科学领域最重要的模式生物之一，被广泛用于发育和疾病研究。",
    description: "斑马鱼体细长、侧扁，体侧有 4–5 条深蓝色的水平纵纹，与银白色的底色相间，就像斑马的花纹，因此得名。成鱼体长一般 3–5 cm，雌鱼腹部较圆，雄鱼体色更鲜艳、体型较瘦长。\n\n斑马鱼原产南亚的印度、孟加拉国、尼泊尔等地的溪流、稻田和沟渠，喜欢清澈的缓流水体。它是杂食性鱼类，吃浮游动物、昆虫幼虫、藻类和鱼卵。繁殖时多在清晨产卵，雌鱼一次可产数百粒卵，胚胎在受精后 24 小时内就发育出主要器官，约 3 天孵化。斑马鱼是生命科学领域的模式生物明星：它的基因组与人类约有 70% 的基因同源，胚胎几乎透明便于直接观察，繁殖周期短、饲养成本低，被广泛用于发育生物学、遗传学、药物筛选和人类疾病模型研究。中国多个城市都建有斑马鱼研究平台，它同时也是水族市场上的常见观赏鱼。目前它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
