    description: "虎皮鱼体呈卵圆形、侧扁，体色金黄或淡黄，体侧有四条醒目的黑色垂直宽纹，因形似虎皮而得名，也有人叫它“四间鱼”。成鱼体长一般 5–7 cm，雌鱼体型比雄鱼更丰满，雄鱼的吻部和鳍条在繁殖期会泛红。\n\n虎皮鱼原产印度尼西亚的苏门答腊、婆罗洲等地的河流和沼泽，喜欢水温较高、弱酸性的软水，常成群活动。它是杂食性鱼类，吃小型甲壳类、昆虫幼虫、藻类和人工饲料。繁殖时雌鱼在水草间产卵，每次数百粒，亲鱼有吞食鱼卵的习性，因此繁殖时通常要把卵隔离。虎皮鱼生性好动，游速快，还会啃咬游动缓慢的鱼的鳍条，混养时需要留意。它是全球水族市场常见的观赏鱼，人工繁殖技术成熟，在部分热带地区也有逃逸个体建立野外种群。目前它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
