    taxonomy: { phylum: "脊索动物门", class: "硬骨鱼纲", order: "鲇形目", family: "鲇科", genus: "鲇属" },
    summary: "中国常见的底栖肉食性鱼类，体表无鳞、口周有须，昼伏夜出，靠嗅觉和触须在浑浊的水底寻找食物。",
    description: "鲶鱼体呈长圆筒形，后部侧扁，头宽扁，口大，上下颌和犁骨上长着细齿。口周有 2–3 对须，其中上颌须最长，用来感知食物。体表无鳞，皮肤光滑且富含黏液；体色灰褐或黄褐，腹部灰白。成鱼体长一般 30–60 cm，体重 0.5–3 kg，最大可超过 1 m。\n\n鲶鱼分布于中国各大水系以及日本、朝鲜半岛，是典型的底栖鱼类。它白天藏在洞穴、石缝和泥底中，夜间才出来觅食；肉食性，捕食小鱼、虾蟹、昆虫、蛙类和水生无脊椎动物，也吃腐肉，口裂很大，能吞下体型不小的猎物。繁殖期在 4–6 月，亲鱼在浅水草区产卵，卵带黏性，黏附在水草和石砾上孵化。鲶鱼适应力强，能在低氧和浑浊的水体中生活，是常见的食用鱼和养殖对象。目前它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
