    taxonomy: { phylum: "脊索动物门", class: "硬骨鱼纲", order: "鲇形目", family: "鲿科", genus: "黄颡鱼属" },
    summary: "中国常见的黄褐色小型鲶类，背鳍和胸鳍有带毒的硬棘，被刺后疼痛难忍，是江河湖泊中常见的食用鱼。",
    description: "黄颡鱼体呈长形，后部侧扁，头宽扁，口大，口周有 4 对须。体表无鳞，体色黄褐，体侧常有不规则的深色斑纹，腹部浅黄。背鳍和胸鳍各有一根坚硬的棘，棘上带有锯齿和毒腺，这是它重要的防御武器。成鱼体长一般 15–25 cm，体重 50–150 g，最大约 30 cm。\n\n黄颡鱼分布于中国长江、黄河、珠江、黑龙江等水系以及朝鲜半岛，是典型的底栖鱼类，喜欢缓流、水草和石缝环境，昼伏夜出。它是杂食偏肉食性鱼类，吃水生昆虫、小鱼、虾类和软体动物。繁殖期在 5–7 月，雄鱼在洞穴中守护鱼卵，直到幼鱼孵化。黄颡鱼的背鳍和胸鳍毒棘是它的防御武器，被刺后伤口会红肿剧痛，处理渔获时需要小心。它是南方江河湖泊中常见的食用小杂鱼，因肉质细嫩、刺少而受欢迎，人工养殖规模也在扩大。目前它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
