    summary: "常见于稻田、沟渠和池塘的小型底栖鱼，体表黏滑、口周有须，能用肠管辅助呼吸，干旱时可以钻入泥中休眠。",
    description: "泥鳅体细长、呈圆柱形，后部侧扁，头小，口下位，口周有 5 对须。体表无鳞，黏液丰富，摸起来非常滑；体色灰褐或黄褐，体侧和背部布满黑色小斑点。成鱼体长一般 10–20 cm，最大约 30 cm，体重通常只有 20–50 g。\n\n泥鳅分布于东亚的稻田、沟渠、池塘和缓流河段，喜欢泥质底和有机质丰富的水体。它是杂食性鱼类，吃水生昆虫、藻类、植物碎屑和腐殖质。泥鳅有两项特别的生存本领：一是能用肠管进行辅助呼吸，水中缺氧时会游到水面吞气，气体经肠道后由肛门排出；二是遇到干旱时能钻入泥中休眠，等雨水回来后重新钻出活动。繁殖期在 4–6 月，雌鱼把卵产在水草和泥底上，卵带黏性。泥鳅是常见的食用小鱼，也可入药，人工养殖较为普遍。目前它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
    habitat: "稻田、沟渠、池塘和缓流河段的泥质底，喜有机质丰富的水体",
