    description: "银鲳体呈卵圆形、侧扁而高，头小，口小，吻部钝圆。体色银白，体表光滑，鳞片细小且容易脱落；背鳍和臀鳍形状相似，呈镰刀状，尾鳍深叉。成鱼体长一般 20–35 cm，体重 0.3–1 kg，最大可超过 40 cm、体重 2 kg 以上。\n\n银鲳分布于印度洋—西太平洋的近岸海域，从波斯湾、印度到中国、日本和朝鲜半岛，中国黄海、东海和南海均产。它栖息于水深 5–110 m 的泥沙底质近海，常成群活动。银鲳是杂食偏肉食性鱼类，吃水母、小鱼、虾类、藻类和有机碎屑。繁殖期在春末夏初，亲鱼在近岸产卵。银鲳肉质细嫩、骨刺少，是中国沿海传统的名贵海产，常见的做法有清蒸和红烧；由于长期捕捞，野生资源有所下降，目前市场上部分银鲳来自养殖。它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
