    description: "鳀鱼体呈细长形、稍侧扁，头大，吻突出，口裂大。体色背部青灰或蓝绿，体侧银白，体侧有一条银白色的纵带，死后容易脱落。成鱼体长一般 10–15 cm，最大约 20 cm，体重 10–30 g，是体型很小的上层鱼类。\n\n鳀鱼分布于西北太平洋，从日本、朝鲜半岛到中国黄海、东海和南海北部，是中国近海数量最多的中上层鱼类之一。它主食浮游甲壳类，尤其是桡足类，靠细密的鳃耙滤食；春季洄游到近岸产卵，卵为浮性。鳀鱼数量大、繁殖快，是蓝点马鲛、带鱼、金枪鱼和海鸟等的重要饵料，也是鱼粉、鱼油和罐头工业的重要原料。由于它在海洋食物链中处于中间位置，其资源量变化会影响到上层捕食者；过度捕捞和海温变化都会造成其种群波动。目前它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
