    description: "大西洋鳕体呈长椭圆形、稍侧扁，头大，口大，下颌有一根明显的须。体色从灰绿、褐黄到深褐不等，体侧散布暗色斑点，腹部银白，侧线明显；背鳍三个，臀鳍两个。成鱼体长一般 60–100 cm，体重 3–10 kg，最大可超过 1.5 m、体重 40 kg 以上。\n\n大西洋鳕分布于北大西洋两岸，包括北美东岸、冰岛、英国、北欧和巴伦支海，是冷水性底层鱼类。它是肉食性动物，捕食小鱼、甲壳类、软体动物和蠕虫；繁殖期在冬春季，成群的鳕鱼在近岸产卵，雌鱼一次可产数百万粒卵。历史上大西洋鳕是欧洲最重要的渔业资源之一，20 世纪因过度捕捞，加拿大纽芬兰等地的鳕鱼群在 1990 年代崩溃并长期禁渔，成为全球渔业管理史上最著名的教训。IUCN 将其评为易危；中国无自然分布，市场上的鳕鱼产品多来自进口。",
