    description: "大比目鱼体呈扁平的卵圆形，两眼都位于身体右侧，这是比目鱼最典型的特征。背面体色灰褐或暗褐色，有时带斑点，腹面白色；口大，牙齿锋利。成鱼体长一般 1–2 m，体重 20–80 kg，最大记录体长可超过 4 m、体重 300 kg 以上，是现存最大的比目鱼之一。\n\n大比目鱼分布于北大西洋，从格陵兰、冰岛、北欧到加拿大东岸和美国东北岸，栖息于水深 50–2000 m 的沙泥底质海域。它是肉食性鱼类，捕食鱼类、乌贼、甲壳类和大型无脊椎动物。大比目鱼生长缓慢、寿命长，可活 50 年以上，性成熟也较晚；繁殖期在冬春季，亲鱼在深海产卵，卵和幼体浮游生活，幼鱼的眼睛会逐渐移到身体同一侧。由于生长慢、肉质名贵，长期捕捞使资源明显减少，IUCN 将其评为濒危；中国无自然分布，市场上的大比目鱼产品多为进口。",
