    description: "鬼头刀也就是鲯鳅，体呈长纺锤形、侧扁。雄鱼的头部钝圆、额部隆起如铲子，雌鱼的头部较尖，这是区分雌雄的明显特征。体色极为艳丽，背部蓝绿或金绿色，两侧金黄并散布蓝色斑点，离水后颜色会迅速变暗。成鱼体长一般 1–1.5 m，体重 10–20 kg，最大可超过 2 m、体重 40 kg 以上。\n\n鬼头刀分布于全球热带和亚热带海洋，是大洋表层鱼类，常聚集在漂浮物和洋流锋面附近。它是肉食性鱼类，捕食小鱼、乌贼和甲壳类；游速快、生长也快，寿命较短，一般只有 3–4 年。繁殖期在温暖海域，雌鱼可以多次产卵。鬼头刀是重要的游钓鱼类和食用鱼，肉质细嫩，常见于热带地区的市场和餐桌，在夏威夷等地还是一道传统菜肴。由于种群分布广、繁殖力强，其资源状况总体尚可。目前它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
