    description: "粒突箱鲀的身体近乎立方体，被由骨板愈合而成的坚硬“盒子”包裹，只有口、眼、鳍和尾部露在外面。幼鱼通体鲜黄，布满黑色圆斑，模样十分可爱；成鱼的颜色转为蓝灰或黄褐色，斑点变淡。成鱼体长一般 30–45 cm。\n\n粒突箱鲀分布于印度洋—太平洋的热带珊瑚礁，包括东非、东南亚、日本南部和澳大利亚北部，中国南海有分布。它栖息于礁区和潟湖，水深 1–40 m，行动缓慢，靠背鳍、臀鳍和尾鳍的摆动游动。它是杂食偏肉食性鱼类，吃藻类、小型无脊椎动物和鱼卵。粒突箱鲀的防御方式很特别：坚硬的骨质外壳让捕食者难以下口，皮肤在受到威胁时还会释放箱鲀毒素，这种毒素在水族箱中可能毒死其他鱼。它通常成对活动，在礁区有相对固定的活动范围。目前它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
