    summary: "体侧有深色斜纹、背鳍末端拖着白色长丝的热带珊瑚礁鱼，成对活动，以珊瑚虫、藻类和小型无脊椎动物为食。",
    description: "扬幡蝴蝶鱼体呈卵圆形、侧扁，吻部尖长，适合在珊瑚缝隙中取食。体色银白或淡黄，体侧有数条深色斜纹，背鳍后部上方拖着一根白色的长丝，像一面飘扬的旗帜，因此得名。成鱼体长一般 15–20 cm，最大约 23 cm。\n\n扬幡蝴蝶鱼分布于印度洋—太平洋的热带珊瑚礁，从红海、东非到日本南部、澳大利亚和夏威夷，中国南海及台湾周边有分布。它栖息于礁区，水深 1–40 m，食性较杂，吃珊瑚虫、藻类、小型甲壳类和多毛类，常成对活动，在礁区有相对固定的活动范围。繁殖时成对产卵，卵为浮性，随水流漂流。蝴蝶鱼科鱼类多靠体侧的花纹识别同类，不同种类的花纹差别很大，这也是它们分类的重要依据。扬幡蝴蝶鱼的背鳍长丝在游动时随水流摆动，十分漂亮，因此也是水族市场上常见的观赏鱼。目前它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
    habitat: "热带珊瑚礁区，水深 1–40 m，常在珊瑚丛和礁石间活动",
    distribution: "印度洋—太平洋热带海域，从红海、东非到日本南部、澳大利亚和夏威夷，中国南海及台湾周边有分布",
