    description: "姥鲨体型庞大，体长一般 6–8 m，最大记录可超过 12 m，是仅次于鲸鲨的第二大鱼类。它体呈纺锤形，吻部尖，鳃裂极长，从头顶一直延伸到喉部附近，鳃耙细密如筛；背鳍高大，体色灰褐或黑灰，皮肤粗糙。\n\n姥鲨分布于全球温带和寒温带的表层海域，包括大西洋、太平洋和南大洋。它是滤食性鱼类，游动时张开大口，靠细密的鳃耙过滤浮游甲壳类、小鱼和鱼卵，一条姥鲨每天要过滤大量海水。姥鲨性情温和，常在海面缓慢巡游，背鳍露出水面，像是在晒太阳，因此得名。它通常单独或成小群活动，有季节性洄游行为。繁殖为卵胎生，妊娠期可能长达数年，每胎数量不多。由于鱼翅、鱼肝油贸易和渔业兼捕，姥鲨种群数量下降，IUCN 将其评为濒危，中国于 2021 年将其列为国家二级保护动物。",
