    description: "非洲肺鱼体呈长圆柱形，像鳗鱼，胸鳍和腹鳍细长呈丝状，尾鳍尖细。体表覆盖着小鳞片，体色灰褐或黄褐，腹部颜色较浅。成鱼体长一般 30–60 cm，最大可超过 1 m。它最特别的结构是鳔：鳔的内部有许多分隔，血管丰富，功能类似肺，可以直接呼吸空气。\n\n非洲肺鱼分布于非洲西部和中部（塞内加尔、尼日尔河、刚果河等流域）的沼泽、湖泊和季节性水体。它是肉食性鱼类，吃鱼类、甲壳类、昆虫和软体动物。旱季水体干涸时，非洲肺鱼会钻进泥中，分泌黏液把周围的泥土黏结成茧，只留一个小孔呼吸，进入休眠状态，等雨季来临再爬出来，这种休眠可以持续数月甚至更久。繁殖期它会在水草间筑巢产卵。非洲肺鱼属于肉鳍鱼类，与四足动物的祖先关系密切，是研究脊椎动物从水到陆演化的重要物种。目前它没有IUCN 的正式评估，中国未将其列入国家重点保护野生动物名录。",
