    description: "护士鲨体呈圆柱形，头部宽扁，口位于头的前下方，口前有一对短触须。背鳍呈圆形，位置靠后，尾鳍长。体色黄褐、灰褐或锈褐色，幼鱼身上常有暗色斑点。成鱼体长一般 2–3 m，最大可达 4 m，体重 100–200 kg。\n\n护士鲨分布于西大西洋热带和亚热带浅海，从美国东南部、加勒比海到巴西沿海，也见于东太平洋部分海域。它是底栖鲨鱼，白天常成群伏在礁石缝和岩洞中休息，夜间出来捕食，用吸食的方式吞下鱼类、甲壳类、软体动物和海胆。护士鲨为卵胎生，每胎可产 20 余尾幼鲨，母鲨有护卵行为。由于栖息地破坏和渔业捕捞，其种群下降，IUCN 将其列为易危。",
    habitat: "热带和亚热带浅海的珊瑚礁、红树林和海草床",
