    description: "豹纹鲨体呈圆柱形，体侧有 5 条纵向的皮褶，尾鳍极长，几乎占体长的一半。幼鱼体色深褐，身上有醒目的白色横纹，像斑马；随着年龄增长，条纹逐渐断裂成斑点，成鱼通体布满深褐色的豹纹状斑点。成鱼体长一般 2–3 m，最大可达 3.5 m。\n\n豹纹鲨分布于印度洋—太平洋的热带和亚热带海域，从东非、红海到日本、澳大利亚，中国南海和台湾周边有分布。它栖息在珊瑚礁、沙地和海草床，水深通常不超过 60 m，夜间活动，以软体动物、甲壳类和小鱼为食。豹纹鲨为卵生，雌鲨产下带触须的卵鞘，卵鞘附着在礁石上。由于沿海开发和观赏鱼贸易，其种群下降，IUCN 将其列为濒危。",
