    description: "欧洲巨鲶体呈长圆筒形，头部宽大，口裂宽，口周有 6 根须，其中下颌须较长。体表无鳞，皮肤光滑，体色灰褐、橄榄褐或黑褐色，腹部浅黄，身上常有深色斑驳。成鱼体长一般 1.5–2 m，最大可达 2.7 m，体重可超过 130 kg，是欧洲最大的淡水鱼。\n\n欧洲巨鲶分布于欧洲中部和东部、西亚的河流、湖泊和水库，从莱茵河、多瑙河到伏尔加河和咸海流域。它栖息在水深、底质复杂的河段，白天多藏在深坑或沉木下，夜间捕食，吃鱼类、两栖类、水鸟、甲壳类，甚至小型哺乳动物。欧洲巨鲶生长快、寿命长，可活 50 年以上。它是游钓爱好者追捧的大型鱼种，也被引入西班牙、意大利等地。目前 IUCN 评估为无危。",
