    summary: "北太平洋的溯河鲑鱼，成鱼体侧银亮、背部暗绿，繁殖期雄鱼下颌弯曲，是重要的商业捕捞和养殖鱼种。",
    description: "银鲑体呈纺锤形，成鱼体侧银亮，背部暗绿或蓝绿，腹部白色，身上有少量黑色小斑点。繁殖期雄鱼体色变暗，背部隆起，下颌向上弯曲成钩状。成鱼体长一般 50–80 cm，最大可达 1 m，体重 3–7 kg。\n\n银鲑分布于北太平洋，从日本北部、俄罗斯远东到美国阿拉斯加和加利福尼亚，亚洲和北美都有溯河种群。它在海洋中生活 1–3 年，性成熟后溯河回到出生溪流产卵，产卵后多数个体死亡。银鲑以小鱼、虾和头足类为食，是重要的商业捕捞和养殖鱼种，鱼肉呈橙红色，适合煎烤和烟熏。由于河流栖息地破坏和过度捕捞，部分种群数量下降，美国已将中加州种群列为濒危，全球评估为无危。",
