    description: "鲫鱼体呈卵圆形，侧扁而高，背鳍长，起点在腹鳍之前，口小，无须。体色背部灰褐或青铜色，体侧金黄或银灰，腹部浅黄。成鱼体长一般 20–40 cm，最大可达 50 cm，体重 1–2 kg。它的鳞片较大，侧线明显，尾鳍分叉。\n\n鲫鱼分布于欧洲中部和东部、西伯利亚至中国北方的河流、湖泊和池塘。它喜欢水流缓慢、水草茂密的水体，耐低氧和低温，冬季能在冰下存活，缺氧时可进行酒精发酵产生能量。鲫鱼是杂食性鱼类，吃浮游动物、昆虫幼虫、藻类和植物碎屑。它生长较慢，但适应力强，是常见的食用鱼和游钓鱼。由于分布广、种群稳定，IUCN 评估为无危。",
