    description: "鱤鱼体呈长梭形，侧扁，头尖，吻部长而尖，口大，下颌前端有突起。体色背部灰褐或青灰，体侧银白，腹部白色，背鳍和尾鳍带灰黑色。成鱼体长一般 1–1.5 m，最大可达 2 m，体重可达 50 kg，是鲤科中体型最大的种类之一。\n\n鱤鱼分布于中国长江、黄河、珠江、黑龙江等水系，栖息在江河的中上层，游速快，性情凶猛，以其他鱼类为食，成鱼能吞食体重数千克的鱼，因此被称为“水老虎”。它在繁殖期溯河而上，在急流中产卵。鱤鱼是江河中的顶级捕食者，对控制小型鱼类数量有一定作用，但也给养殖业带来危害。由于过度捕捞和水利工程，野生种群下降，目前尚无明确的 IUCN 评估。",
    habitat: "江河中上层，喜欢水流较急、溶氧充足的江段",
