    summary: "东亚溪流中的小型鲤科鱼类，雄鱼繁殖期体色鲜艳、口裂呈马口状，喜清澈急流，是溪流钓的常见对象。",
    description: "马口鱼体呈长形，侧扁，头尖，口大，口裂向上倾斜，像马嘴，因此得名。雄鱼在繁殖期体色鲜艳，体侧有蓝绿色金属光泽，腹鳍和臀鳍呈橙红色；雌鱼体色较淡。成鱼体长一般 10–20 cm，最大可达 25 cm。\n\n马口鱼分布于中国、日本、朝鲜半岛和俄罗斯远东的溪流、江河上游和水库，喜欢水质清澈、水流较急、砾石底质的环境。它是肉食性鱼类，捕食水生昆虫、小鱼和虾，也吃藻类。繁殖期在春夏季，雄鱼会追逐雌鱼，在水流平缓的沙砾底产卵。马口鱼个体不大，但咬钩凶猛，是溪流钓爱好者喜爱的对象，也可油炸食用。目前尚无明确的 IUCN 评估。",
    habitat: "水质清澈、水流较急、砾石底质的溪流和江河上游",
