    description: "高体鳑鲏体呈卵圆形，侧扁而高，头小，口小。雄鱼在繁殖期体色鲜艳，体侧有蓝绿色光泽，腹部和鳍条呈橙红色；雌鱼体色较淡，腹部有产卵管。成鱼体长一般 5–8 cm，最大可达 10 cm。\n\n高体鳑鲏分布于中国长江以南的溪流、池塘和沟渠，也见于日本和朝鲜半岛。它栖息在水草茂密、水流缓慢的水体，以藻类和有机碎屑为食。繁殖方式十分特别：雌鱼用产卵管把卵产进河蚌的鳃腔，雄鱼随后在蚌的入水管口排精，卵在蚌体内受精发育；鳑鲏的卵也会被蚌的幼体寄生，形成互利共生。由于河蚌资源减少和水体污染，部分种群下降，目前尚无明确的 IUCN 评估。",
