    description: "鮟鱇体呈扁平的卵圆形，头部特别大，口裂宽，牙齿尖锐并向后倾斜。体表光滑无鳞，体色灰褐、黄褐或黑褐色，常与海底泥沙相似。背鳍第一棘特化成细长的“钓竿”，末端有一个肉质“诱饵”，用来引诱猎物。成鱼体长一般 1–2 m，体重可达 20 kg 以上。\n\n鮟鱇分布于东北大西洋、地中海和黑海，栖息在沙泥底质的大陆架和大陆坡，水深可达 1000 m。它是底栖伏击型捕食者，常把身体埋在泥沙中，只露出诱饵，等小鱼和甲壳类靠近时突然张口吞下。鮟鱇肉质紧实，鱼肝肥美，是欧洲重要的食用鱼。由于拖网捕捞和生长缓慢，其种群受到压力，目前 IUCN 评估为无危。",
