    description: "黑鳍礁鲨体形修长，成年体长一般 1.0–1.6 米，最大约 1.8 米，体重 10–25 千克。背侧呈灰褐至黄褐色，腹面白色，最醒目的特征是背鳍、胸鳍、腹鳍与尾鳍下叶的尖端均为黑色，背鳍前缘下方还有一块明显的浅色长斑。吻部短而钝圆，眼小，喷水孔消失，牙呈窄三角形。\n\n它们广泛分布于印度洋与西太平洋的热带珊瑚礁，栖息于礁坪、潟湖、红树林与河口浅水，常在不足一米深的水中巡游，背鳍露出水面。食性以鱼类、头足类、甲壳类为主，也捕食海蛇与小型鳐类。它们对温度与盐度变化耐受性强，会在潮汐驱动下在礁坪与潟湖间移动。繁殖为胎生，每胎 2–5 尾，妊娠期约 8–9 个月。由于近岸捕捞、礁区破坏与旅游干扰，其种群在部分区域下降，被列为易危物种。",
