    summary: "外形酷似礁石或长满藻类的石块，背鳍十三根毒棘可注入剧毒，是世界上最毒的鱼类之一，被刺后疼痛剧烈甚至危及生命。",
    description: "石头鱼体形粗短肥胖，体长约 30–40 厘米，体重 1–2 千克。皮肤粗糙、布满疣状突起，没有鳞片，体色灰褐、暗红或黄褐，表面常附生藻类，与礁石、珊瑚碎块几乎无法分辨，是极致的伪装者。头部宽大，口大向上，眼小位于头顶；胸鳍宽大呈扇形，可支撑身体伏在海底。背鳍有 13 根粗壮的毒棘，每根棘基部有毒腺，棘外套着薄皮鞘，受压时毒液注入伤口。\n\n它们分布于印度洋与太平洋的浅海礁区、沙底与河口，多静伏不动，等小鱼、虾、蟹靠近时突然张口吸入。石头鱼不主动攻击人，但被踩到或触碰时毒棘会立即竖起刺入，毒液含神经毒素与溶血毒素，可引起剧烈疼痛、肿胀、组织坏死，严重时导致呼吸麻痹。急救需将伤处浸入热水以破坏毒素并立即就医。它们可食用，肉质细嫩，但处理时必须小心去除毒棘。",
    habitat: "浅海珊瑚礁、岩礁、沙底与河口，常静伏于礁石或沙中",
    distribution: "印度洋与太平洋热带海域，从红海、东非至日本南部、澳大利亚与波利尼西亚",
