    description: "雀鳝是北美最大的淡水鱼之一，成年体长 1.5–2.5 米，最大记录超过 3 米，体重 50–100 千克。体形修长呈圆柱状，吻部极长而扁平，上下颌密布尖锐的锥形齿，形似鳄鱼的口鼻，故又称鳄雀鳝；体被菱形硬鳞，表面覆一层釉质，坚硬如铠甲。背鳍与臀鳍位于身体极后部，尾鳍圆形，体色橄榄褐至灰绿，腹部浅白，体侧常带深色斑点。\n\n它们分布于美国南部与墨西哥东北部的河流、湖泊、沼泽与河口，偏好水流缓慢、植被茂密的水体。雀鳝是伏击型猎手，常静浮于水面附近，待鱼、蟹、水鸟靠近时突然侧向咬击。它的鳔特化为类似肺的结构，可直接吞入空气呼吸，因此在溶氧极低的水中也能生存。繁殖期在春季，雌鱼产下带毒的卵，卵黏附于水草。由于外形凶悍、被误传为“食人鱼”，它常遭捕杀；作为观赏鱼被引入亚洲后，又成为难以清除的外来入侵种。",
